// Read-only: count users whose stored list holds repeated ids, by day prefix.
const fs = require('node:fs');
const s = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
let users = 0, withDup = 0, dupIds = 0;
const dupDays = {};
for (const [u, data] of Object.entries(s)) {
  users++;
  const raw = Object.values(data)[0];
  let todos = [];
  try { const p = JSON.parse(raw); todos = Array.isArray(p) ? p : (p.todos || []); } catch { continue; }
  const seen = new Map();
  for (const t of todos) seen.set(t.id, (seen.get(t.id) || 0) + 1);
  const d = [...seen].filter(([, c]) => c > 1);
  if (d.length) {
    withDup++; dupIds += d.length;
    for (const [id] of d) { const day = id.split('-')[1]; dupDays[day] = (dupDays[day] || 0) + 1; }
  }
}
console.log(JSON.stringify({ file: process.argv[2], users, withDup, dupIds, dupDays }));

